18	 *   heading       "CloudScale AI Inference Gateway"
19	 * Keep those labels unique on the page: Kane finds controls by their text.
20	 */
21	
22	const NAV = [
23	  { id: "keys", label: "API keys" },
24	  { id: "quota", label: "Quota" },
25	  { id: "activity", label: "Activity" },
