39	function ago(iso: string, now: number) {
40	  const s = Math.max(0, Math.round((now - new Date(iso).getTime()) / 1000));
41	  if (s < 10) return "just now";
42	  if (s < 60) return `${s}s ago`;
43	  if (s < 3600) return `${Math.round(s / 60)} min ago`;
44	  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
45	  return `${Math.round(s / 86400)} d ago`;
46	}
