68	/** Re-render periodically so relative times stay current. */
69	function useNow(ms = 15_000) {
70	  const [now, setNow] = useState(() => Date.now());
71	  useEffect(() => {
72	    const t = setInterval(() => setNow(Date.now()), ms);
73	    return () => clearInterval(t);
74	  }, [ms]);
75	  return now;
76	}
