93	
94	  useEffect(() => {
95	    setRunScope(runId());
96	  }, []);
97	
98	  // Re-reads the whole workspace. Called on load and after every write, so the
99	  // dashboard shows what the server holds now, not what this tab last saw.
100	  const refresh = useCallback(async () => {
101	    setState(await call<CloudScaleState>("/api/cloudscale"));
102	  }, []);
103	
104	  useEffect(() => {
105	    refresh().catch((e: Error) => setError(e.message));
106	  }, [refresh]);
107	
108	  const run = useCallback(async (fn: () => Promise<void>) => {
109	    setBusy(true);
110	    setError(null);
111	    try {
112	      await fn();
113	    } catch (e) {
114	      setError((e as Error).message);
