333	              <div className="overflow-x-auto">
334	                <table className="w-full text-left">
335	                  <thead className="text-xs text-cs-sub">
336	                    <tr className="border-b border-cs-line">
337	                      <th className="px-4 py-2 font-normal">Name</th>
338	                      <th className="px-4 py-2 font-normal">Key</th>
339	                      <th className="px-4 py-2 font-normal hidden sm:table-cell">Rate limit</th>
340	                      <th className="px-4 py-2 font-normal">Created</th>
341	                    </tr>
342	                  </thead>
343	                  <tbody>
344	                    {!state && (
345	                      <tr>
346	                        <td colSpan={4} className="px-4 py-6 text-center text-cs-sub">
347	                          Loading keys…
348	                        </td>
349	                      </tr>
350	                    )}
351	                    {(state?.keys ?? []).map((k) => (
352	                      <tr key={k.id} className="border-b border-cs-line last:border-0">
353	                        <td className="px-4 py-3">
354	                          <div className="font-medium">{k.name}</div>
355	                          <div className="text-xs text-cs-sub">{k.id}</div>
356	                        </td>
357	                        <td className="px-4 py-3 font-mono text-xs">{k.prefix}••••</td>
358	                        <td className="px-4 py-3 hidden sm:table-cell tabular-nums">
359	                          {k.rateLimitPerMin.toLocaleString("en-US")} / min
360	                        </td>
361	                        <td className="px-4 py-3 text-cs-sub tabular-nums">
362	                          {k.createdAt.slice(0, 10)} · {ago(k.createdAt, now)}
363	                        </td>
364	                      </tr>
365	                    ))}
366	                  </tbody>
367	                </table>
368	              </div>
369	            </section>
370	
371	            <div className="mt-8 grid lg:grid-cols-[1fr_20rem] gap-6 items-start">
372	              {/* Activity */}
373	              <section id="activity" className="rounded-lg border border-cs-line bg-white scroll-mt-6">
374	                <div className="px-4 py-4 border-b border-cs-line flex items-baseline justify-between gap-3">
375	                  <h2 className="font-medium">Activity</h2>
376	                  <span className="text-xs text-cs-sub">Audit log · newest first</span>
377	                </div>
378	                <ol data-testid="activity-log">
379	                  {activity.length === 0 && <li className="px-4 py-6 text-center text-cs-sub">No activity yet.</li>}
380	                  {activity.map((a, i) => (
381	                    <li key={`${a.at}-${i}`} className="px-4 py-3 border-b border-cs-line last:border-0 flex items-start gap-3">
382	                      <span className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${KIND_DOT[a.kind]}`} />
383	                      <div className="min-w-0 flex-1">
384	                        <div>{a.message}</div>
385	                        <div className="text-xs text-cs-sub font-mono">{a.kind}</div>
386	                      </div>
387	                      <time dateTime={a.at} className="shrink-0 text-xs text-cs-sub tabular-nums" title={a.at}>
388	                        {ago(a.at, now)}
389	                      </time>
390	                    </li>
391	                  ))}
392	                </ol>
393	              </section>
394	
395	              {/* Billing summary */}
396	              <section className="rounded-lg border border-cs-line bg-white">
397	                <div className="px-4 py-4 border-b border-cs-line">
398	                  <h2 className="font-medium">Billing</h2>
399	                </div>
400	                <dl className="px-4 py-3 grid grid-cols-[1fr_auto] gap-y-2 text-xs">
401	                  <dt className="text-cs-sub">Plan</dt>
402	                  <dd>Team · prepaid</dd>
403	                  <dt className="text-cs-sub">Top-up increment</dt>
404	                  <dd className="tabular-nums">{formatUsd(TOPUP_CENTS)}</dd>
405	                  <dt className="text-cs-sub">Top-ups since reset</dt>
406	                  <dd className="tabular-nums">{since("quota.topup")}</dd>
407	                  <dt className="text-cs-sub">Keys issued since reset</dt>
408	                  <dd className="tabular-nums">{since("key.created")}</dd>
409	                </dl>
410	                <p className="px-4 pb-4 text-xs text-cs-sub leading-relaxed">
411	                  Driftor restores this workspace to its seed state before every Kane run, so every check starts from the
412	                  same keys and balance.
413	                </p>
414	              </section>
415	            </div>
416	          </main>
417	        </div>
418	      </div>
419	    </div>
420	  );
421	}
