                      <th className="px-4 py-2 font-normal">Key</th>
                      <th className="px-4 py-2 font-normal hidden sm:table-cell">Rate limit</th>
                      <th className="px-4 py-2 font-normal">Created</th>
                    </tr>
                  </thead>
