          </div>
          <nav className="px-3 flex flex-col gap-0.5" aria-label="Sections">
            {NAV.map((item) => (
              <a key={item.id} href={`#${item.id}`} className="rounded-md px-3 py-1.5 text-cs-sub hover:bg-zinc-100 hover:text-cs-text">
